function.arguments:
{"sql": "SELECT COUNT(*) FROM (
  WITH ny_2012 AS (
    SELECT CoC_Number FROM `bigquery-public-data.sdoh_hud_pit_homelessness.hud_pit_by_coc`
    WHERE CoC_Number LIKE 'NY%' AND Count_Year = 2012
  ),
  ny_2018 AS (
    SELECT CoC_Number FROM `bigquery-public-data.sdoh_hud_pit_homelessness.hud_pit_by_coc`
    WHERE CoC_Number LIKE 'NY%' AND Count_Year = 2018
  )
  SELECT a.CoC_Number FROM ny_2012 a INNER JOIN ny_2018 b ON a.CoC_Number = b.CoC_Number
)"}
